#include <stdio.h>

int main() {                                           // main function — yahan se shuru hota hai
    int marks = 85;   // the value we want to test

    // ── if-else chain ──────────────────────────────────────────
    if (marks >= 90)       printf("Grade: A\n");   // highest: 90 and above
    else if (marks >= 80)  printf("Grade: B\n");   // second: 80 to 89
    else if (marks >= 70)  printf("Grade: C\n");   // third: 70 to 79
    else if (marks >= 60)  printf("Grade: D\n");   // passing: 60 to 69
    else                   printf("Grade: F\n");   // failing: below 60

    // ── Ternary operator (one-line if-else) ───────────────────
    char *result = (marks >= 60) ? "Pass" : "Fail";   // condition ? true : false
    printf("Result: %s\n", result);   // Pass

    // ── switch statement (for discrete values) ────────────────
    int day = 3;                                       // integer variable
    switch (day) {                    // evaluate expression once
        case 1: printf("Monday\n");    break;   // break prevents fall-through
        case 2: printf("Tuesday\n");   break;          // output print karo
        case 3: printf("Wednesday\n"); break;   // matches day=3
        case 6:                                  // fall-through (no break)
        case 7: printf("Weekend!\n");  break;   // both 6 and 7 reach here
        default: printf("Other day\n");         // none of the cases matched
    }

    // ── Logical operators ─────────────────────────────────────
    int age = 20;                                      // integer variable
    if (age >= 18 && age <= 60)    // && = AND (both must be true)
        printf("Working age\n");                       // output print karo
    if (marks > 90 || age < 18)   // || = OR (at least one must be true)
        printf("Special case\n");                      // output print karo
    if (!(marks < 60))             // ! = NOT (reverses condition)
        printf("Not failing\n");                       // output print karo

    return 0;                                          // value return karo
}

#include <stdio.h>

int main() {                                           // main function — yahan se shuru hota hai
    // ── for loop: init; condition; update ──────────────────────
    printf("For loop: ");                              // output print karo
    for (int i = 1; i <= 5; i++) {     // i starts at 1, runs while i<=5, i++ each time
        printf("%d ", i);               // prints: 1 2 3 4 5
    }
    printf("\n");                                      // output print karo

    // ── for loop counting down ─────────────────────────────────
    printf("Countdown: ");                             // output print karo
    for (int i = 10; i > 0; i -= 2) {  // i decreases by 2 each time
        printf("%d ", i);               // prints: 10 8 6 4 2
    }
    printf("\n");                                      // output print karo

    // ── while loop: check condition BEFORE each iteration ──────
    printf("While: ");                                 // output print karo
    int n = 5;                                         // integer variable
    while (n > 0) {     // check condition first — if false, never runs
        printf("%d ", n);                              // output print karo
        n--;             // MUST update n or this is an infinite loop!
    }
    printf("\n");       // prints: 5 4 3 2 1

    // ── do-while loop: runs AT LEAST once (checks after) ───────
    printf("Do-While: ");                              // output print karo
    int x = 1;                                         // integer variable
    do {
        printf("%d ", x);   // body runs FIRST, then check condition
        x++;
    } while (x <= 5);       // condition checked after each iteration
    printf("\n");           // prints: 1 2 3 4 5

    // ── Nested loop (multiplication table) ────────────────────
    printf("Multiplication table (3x3):\n");           // output print karo
    for (int i = 1; i <= 3; i++) {      // outer: row number
        for (int j = 1; j <= 3; j++) {  // inner: column number
            printf("%2d ", i * j);       // %2d = 2 character wide
        }
        printf("\n");   // new row
    }

    // ── break and continue ─────────────────────────────────────
    printf("Skip evens, stop at 8: ");                 // output print karo
    for (int i = 1; i <= 10; i++) {                    // integer variable
        if (i % 2 == 0) continue;   // skip current iteration (don't print even)
        if (i == 9)     break;      // exit loop entirely
        printf("%d ", i);           // prints: 1 3 5 7
    }

    return 0;                                          // value return karo
}

