// Bubble sort function
void bubbleSort(int arr[], int n) {                    // function define karo
    for (int i = 0; i < n-1; i++)             // n-1 passes needed
        for (int j = 0; j < n-i-1; j++)       // compare up to unsorted part
            if (arr[j] > arr[j+1]) {           // if left > right (wrong order)
                int t = arr[j];                // swap using temp variable
                arr[j] = arr[j+1];
                arr[j+1] = t;
            }
}

