int main() {                                           // main function — yahan se shuru hota hai
    char s1[50] = "Hello";    // string as character array (size must be large enough)
    char s2[] = " World";     // another string
    char s3[50];              // empty string to fill later

    // ── String length ──────────────────────────────────────────
    printf("Length: %lu\n", strlen(s1));       // 5 (doesn't count \0 terminator)

    // ── Concatenate (join) strings ─────────────────────────────
    strcat(s1, s2);                             // s1 = s1 + s2 = "Hello World"
    printf("Concat: %s\n", s1);                // Hello World

    // ── Copy string ────────────────────────────────────────────
    strcpy(s3, "QueryNest");                    // copies "QueryNest" into s3
    printf("Copy:   %s\n", s3);                // QueryNest

    // ── Compare strings ────────────────────────────────────────
    printf("Equal:  %d\n", strcmp("abc","abc"));   // 0 means equal
    printf("Less:   %d\n", strcmp("abc","abd"));   // negative means first is less

    // ── Search in string ───────────────────────────────────────
    char *pos = strstr(s1, "World");            // find "World" in s1
    if (pos) printf("Found at position: %ld\n", pos - s1);  // 6

    // ── Convert case ───────────────────────────────────────────
    char str[] = "Hello World";                        // character variable
    for (int i = 0; str[i]; i++) str[i] = toupper(str[i]);   // convert each char
    printf("Upper: %s\n", str);                // HELLO WORLD

    // ── Reverse a string ───────────────────────────────────────
    char rev[] = "Python";                             // character variable
    int len = strlen(rev);                             // integer variable
    for (int i = 0; i < len/2; i++) {          // swap characters from both ends
        char t = rev[i];                               // character variable
        rev[i] = rev[len-1-i];
        rev[len-1-i] = t;
    }
    printf("Reverse: %s\n", rev);              // nohtyP

    // ── Tokenize (split by delimiter) ─────────────────────────
    char csv[] = "Alice,20,Mumbai";                    // character variable
    char *token = strtok(csv, ",");             // get first token before ','
    while (token) {                                    // jab tak condition True ho
        printf("Token: %s\n", token);                  // output print karo
        token = strtok(NULL, ",");             // NULL continues from last position
    }
    return 0;                                          // value return karo
}

