// Check if string is palindrome: reads same forward and backward
int isPalindromeStr(char s[]) {                        // character variable
    int l = 0;                 // left pointer starts at beginning
    int r = strlen(s) - 1;    // right pointer starts at end
    while (l < r) {            // continue until pointers meet in middle
        if (s[l] != s[r]) return 0;   // mismatch found — not palindrome
        l++;   // move left pointer right
        r--;   // move right pointer left
    }
    return 1;   // all characters matched — is palindrome
}

// Check if number is palindrome: reverse it and compare
int isPalindromeNum(int n) {                           // integer return karne wala function
    if (n < 0) return 0;         // negative numbers are not palindromes
    int orig = n, rev = 0;                             // integer variable
    while (n > 0) {                                    // jab tak condition True ho
        rev = rev * 10 + n % 10;  // build reversed number digit by digit
        n /= 10;                   // remove last digit
    }
    return orig == rev;            // compare original with reversed
}

