#include <stdio.h>

int main() {                                           // main function — yahan se shuru hota hai
    int n = 5;   // number of rows in each pattern

    // ── Pattern 1: Right triangle ──────────────────────────────
    printf("Right Triangle:\n");                       // output print karo
    for (int i = 1; i <= n; i++) {          // i = row number (1 to n)
        for (int j = 0; j < i; j++)         // print i stars in row i
            printf("* ");                              // output print karo
        printf("\n");                       // move to next line
    }

    // ── Pattern 2: Inverted triangle ──────────────────────────
    printf("\nInverted Triangle:\n");                  // output print karo
    for (int i = n; i >= 1; i--) {          // i decreases from n to 1
        for (int j = 0; j < i; j++)                    // integer variable
            printf("* ");                              // output print karo
        printf("\n");                                  // output print karo
    }

    // ── Pattern 3: Pyramid ─────────────────────────────────────
    printf("\nPyramid:\n");                            // output print karo
    for (int i = 1; i <= n; i++) {                     // integer variable
        for (int j = i; j < n; j++) printf(" ");    // leading spaces (decreasing)
        for (int j = 1; j <= 2*i-1; j++) printf("*"); // stars (increasing: 1,3,5,7,9)
        printf("\n");                                  // output print karo
    }

    // ── Pattern 4: Diamond ─────────────────────────────────────
    printf("\nDiamond:\n");                            // output print karo
    for (int i = 1; i <= n; i++) {          // upper half
        for (int j = i; j < n; j++) printf(" ");       // output print karo
        for (int j = 1; j <= 2*i-1; j++) printf("*");  // output print karo
        printf("\n");                                  // output print karo
    }
    for (int i = n-1; i >= 1; i--) {        // lower half (skip middle row)
        for (int j = n; j > i; j--) printf(" ");       // output print karo
        for (int j = 1; j <= 2*i-1; j++) printf("*");  // output print karo
        printf("\n");                                  // output print karo
    }

    // ── Pattern 5: Number triangle ─────────────────────────────
    printf("\nNumber Triangle:\n");                    // output print karo
    for (int i = 1; i <= n; i++) {                     // integer variable
        for (int j = 1; j <= i; j++) printf("%d ", j);  // 1, 1 2, 1 2 3, ...
        printf("\n");                                  // output print karo
    }

    return 0;                                          // value return karo
}

