// ── Bubble Sort: repeatedly swap adjacent out-of-order elements ────
void bubbleSort(int arr[], int n) {                    // function define karo
    for (int i = 0; i < n-1; i++) {         // n-1 passes
        for (int j = 0; j < n-i-1; j++) {   // last i elements are already sorted
            if (arr[j] > arr[j+1]) {         // wrong order
                int t = arr[j]; arr[j] = arr[j+1]; arr[j+1] = t;   // swap
            }
        }
    }
}

// ── Selection Sort: find minimum and place it at correct position ──
void selectionSort(int arr[], int n) {                 // function define karo
    for (int i = 0; i < n; i++) {                      // integer variable
        int minIdx = i;                       // assume current position is minimum
        for (int j = i+1; j < n; j++)        // search remaining array
            if (arr[j] < arr[minIdx]) minIdx = j;  // found new minimum
        // swap minimum to position i
        int t = arr[i]; arr[i] = arr[minIdx]; arr[minIdx] = t; // integer variable
    }
}

// ── Insertion Sort: build sorted array one element at a time ───────
void insertionSort(int arr[], int n) {                 // function define karo
    for (int i = 1; i < n; i++) {                      // integer variable
        int key = arr[i];    // element to be inserted into sorted portion
        int j = i - 1;                                 // integer variable
        while (j >= 0 && arr[j] > key) {  // shift larger elements right
            arr[j+1] = arr[j];
            j--;
        }
        arr[j+1] = key;      // insert key at correct position
    }
}

