#define N 3   // matrix size (N×N) — #define creates a constant

// Multiply two N×N matrices: C = A × B
void multiply(int A[N][N], int B[N][N], int C[N][N]) { // function define karo
    for (int i = 0; i < N; i++) {           // row of result matrix
        for (int j = 0; j < N; j++) {       // column of result matrix
            C[i][j] = 0;                    // initialize cell to 0
            for (int k = 0; k < N; k++) {   // dot product: multiply row of A × column of B
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

// Transpose: swap rows and columns
void transpose(int M[N][N], int T[N][N]) {             // function define karo
    for (int i = 0; i < N; i++)                        // integer variable
        for (int j = 0; j < N; j++)                    // integer variable
            T[j][i] = M[i][j];   // T[j][i] = M[i][j] swaps row/column
}

// Print matrix with label
void printMatrix(int M[N][N], char *label) {           // function define karo
    printf("%s:\n", label);                            // output print karo
    for (int i = 0; i < N; i++) {                      // integer variable
        for (int j = 0; j < N; j++) printf("%4d", M[i][j]);  // %4d = 4 chars wide
        printf("\n");                                  // output print karo
    }
}

int main() {                                           // main function — yahan se shuru hota hai
    int A[N][N] = {{1,2,3},{4,5,6},{7,8,9}};   // matrix A
    int B[N][N] = {{9,8,7},{6,5,4},{3,2,1}};   // matrix B
    int C[N][N];   // result matrix (uninitialized)
    int T[N][N];   // transpose matrix

    printMatrix(A, "Matrix A");
    printMatrix(B, "Matrix B");

    multiply(A, B, C);       // C = A × B
    printMatrix(C, "A × B");

    transpose(A, T);         // T = Aᵀ
    printMatrix(T, "Transpose of A");

    return 0;                                          // value return karo
}

