#include <math.h>   // for pow()

// Armstrong number: sum of digits^(number of digits) equals the number
// Example: 153 = 1³ + 5³ + 3³ = 1 + 125 + 27 = 153 ✓
int isArmstrong(int n) {                               // integer return karne wala function
    int temp   = n;        // save original value for final comparison
    int digits = 0;        // count number of digits
    while (temp) {                                     // jab tak condition True ho
        digits++;          // count each digit
        temp /= 10;        // remove last digit
    }
    temp = n;              // reset temp to original
    int sum = 0;                                       // integer variable
    while (temp) {                                     // jab tak condition True ho
        int d = temp % 10;                     // extract last digit
        sum += (int)pow(d, digits);            // add digit^power to sum
        temp /= 10;                            // remove last digit
    }
    return sum == n;   // true if sum equals original number
}

int main() {                                           // main function — yahan se shuru hota hai
    // ── Check specific numbers ─────────────────────────────────
    int nums[] = {153, 370, 371, 407, 9474, 100, 200};
    int len = sizeof(nums) / sizeof(nums[0]);   // array length
    for (int i = 0; i < len; i++)                      // integer variable
        printf("%4d: %s\n", nums[i],                   // output print karo
               isArmstrong(nums[i]) ? "Armstrong ✓" : "Not Armstrong ✗");

    // ── Find all Armstrong numbers in range ────────────────────
    printf("\nArmstrong numbers (1 to 9999):\n");      // output print karo
    for (int i = 1; i <= 9999; i++)                    // integer variable
        if (isArmstrong(i)) printf("%d ", i);          // output print karo
    printf("\n");                                      // output print karo
    // Output: 1 2 3 4 5 6 7 8 9 153 370 371 407 1634 8208 9474

    return 0;                                          // value return karo
}

#include <stdio.h>

// GCD using Euclidean algorithm (most efficient)
// Principle: GCD(a, b) = GCD(b, a % b) until b = 0
int gcd(int a, int b) {                                // integer return karne wala function
    return b == 0 ? a : gcd(b, a % b);   // when b=0, GCD is a; else recurse
}

// LCM formula: LCM(a,b) = (a × b) / GCD(a,b)
int lcm(int a, int b) {                                // integer return karne wala function
    return a / gcd(a, b) * b;   // divide first to avoid overflow
}

// Sum of digits of a number
int sumDigits(int n) {                                 // integer return karne wala function
    int sum = 0;                                       // integer variable
    while (n > 0) {                                    // jab tak condition True ho
        sum += n % 10;   // add last digit to sum
        n /= 10;         // remove last digit
    }
    return sum;                                        // value return karo
}

// Reverse a number
int reverseNum(int n) {                                // integer return karne wala function
    int rev = 0;                                       // integer variable
    while (n > 0) {                                    // jab tak condition True ho
        rev = rev * 10 + n % 10;   // shift rev left and add last digit of n
        n /= 10;                    // remove last digit from n
    }
    return rev;                                        // value return karo
}

// Check if number is perfect (sum of divisors = number)
int isPerfect(int n) {                                 // integer return karne wala function
    if (n <= 1) return 0;                              // condition check karo
    int sum = 1;           // 1 is always a divisor
    for (int i = 2; i * i <= n; i++) {                 // integer variable
        if (n % i == 0) {                              // condition check karo
            sum += i;      // add divisor i
            if (i != n/i) sum += n/i;  // add paired divisor (avoid duplicates)
        }
    }
    return sum == n;                                   // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    printf("GCD(48, 18)    = %d\n", gcd(48, 18));    // 6
    printf("GCD(100, 75)   = %d\n", gcd(100, 75));   // 25
    printf("LCM(4, 6)      = %d\n", lcm(4, 6));      // 12
    printf("LCM(12, 18)    = %d\n", lcm(12, 18));    // 36
    printf("Sum digits(1234)= %d\n", sumDigits(1234)); // 10
    printf("Reverse(12345) = %d\n", reverseNum(12345)); // 54321

    printf("\nPerfect numbers (1-1000): ");            // output print karo
    for (int i = 2; i <= 1000; i++)                    // integer variable
        if (isPerfect(i)) printf("%d ", i);   // 6 28 496
    printf("\n");                                      // output print karo

    return 0;                                          // value return karo
}

#include <stdio.h>

// Tower of Hanoi: move n disks from 'from' peg to 'to' peg using 'aux' peg
// Rule: only one disk at a time, never place larger disk on smaller
void hanoi(int n, char from, char to, char aux) {      // character variable
    if (n == 1) {                                      // condition check karo
        printf("Move disk 1: %c → %c\n", from, to);   // base: just move the one disk
        return;
    }
    hanoi(n-1, from, aux, to);   // Step 1: move top n-1 disks to aux peg
    printf("Move disk %d: %c → %c\n", n, from, to);  // Step 2: move largest disk
    hanoi(n-1, aux, to, from);   // Step 3: move n-1 disks from aux to target
}

// Fast power using recursion (O(log n) — much faster than O(n))
long power(int base, int exp) {
    if (exp == 0) return 1;        // base case: anything^0 = 1
    if (exp % 2 == 0) {            // even exponent optimization
        long half = power(base, exp/2);  // compute half
        return half * half;              // square it instead of multiplying n times
    }
    return base * power(base, exp-1);  // odd exponent
}

// Count digits using recursion
int countDigits(int n) {                               // integer return karne wala function
    if (n < 10) return 1;               // base case: single digit
    return 1 + countDigits(n / 10);     // remove last digit, count rest
}

int main() {                                           // main function — yahan se shuru hota hai
    // Tower of Hanoi with 3 disks
    printf("Tower of Hanoi (3 disks):\n");             // output print karo
    hanoi(3, 'A', 'C', 'B');    // move 3 disks from A to C using B as helper
    printf("Total moves = 2^n - 1 = %d\n\n", (int)power(2,3) - 1);  // 7

    printf("2^10 = %ld\n", power(2, 10));      // 1024
    printf("3^5  = %ld\n", power(3, 5));        // 243
    printf("Digits in 12345: %d\n", countDigits(12345));  // 5

    return 0;                                          // value return karo
}

