void bubbleSort(int arr[], int n) {                    // function define karo
    for (int i = 0; i < n-1; i++) {                    // integer variable
        int swapped = 0;                               // integer variable
        for (int j = 0; j < n-i-1; j++) {              // integer variable
            if (arr[j] > arr[j+1]) {                   // condition check karo
                int t = arr[j]; arr[j] = arr[j+1]; arr[j+1] = t; // integer variable
                swapped = 1;
            }
        }
        if (!swapped) break;  // Already sorted
    }
}

