#define MAX 100

int stack[MAX], top = -1;

void push(int x) {                                     // function define karo
    if (top == MAX-1) { printf("Stack overflow!\n"); return; } // output print karo
    stack[++top] = x;
}
int pop() {                                            // integer return karne wala function
    if (top == -1) { printf("Stack underflow!\n"); return -1; } // output print karo
    return stack[top--];                               // value return karo
}
int peek() { return top == -1 ? -1 : stack[top]; }     // value return karo

