}

#include <stdio.h>
#define MAX 100

int queue[MAX], front = 0, rear = -1, size = 0;

void enqueue(int x) {                                  // function define karo
    if (size == MAX) { printf("Queue full!\n"); return; } // output print karo
    rear = (rear + 1) % MAX;
    queue[rear] = x; size++;
}
int dequeue() {                                        // integer return karne wala function
    if (size == 0) { printf("Queue empty!\n"); return -1; } // output print karo
    int val = queue[front];                            // integer variable
    front = (front + 1) % MAX; size--;
    return val;                                        // value return karo
}

int main() {                                           // main function — yahan se shuru hota hai
    enqueue(10); enqueue(20); enqueue(30);
    printf("Dequeue: %d\n", dequeue()); // 10
    printf("Dequeue: %d\n", dequeue()); // 20
    return 0;                                          // value return karo
}

